   250   * @param  maxIdx      Size of out and scratch arrays (must be
   251   * maxGridDiskSize(k))
   252   * @param  curK        Current distance from the origin
   253   */
   254  H3Error _gridDiskDistancesInternal(H3Index origin, int k, H3Index *out,
   255                                     int *distances, int64_t maxIdx, int curK) {
   256      // Put origin in the output array. out is used as a hash set.
   257      int64_t off = origin % maxIdx;
   258      while (out[off] != 0 && out[off] != origin) {
   259          off = (off + 1) % maxIdx;
   260      }
   261
   262      // We either got a free slot in the hash set or hit a duplicate
   263      // We might need to process the duplicate anyways because we got
   264      // here on a longer path before.
   265      if (out[off] == origin && distances[off] <= curK) return E_SUCCESS;
   266
   267      out[off] = origin;
   268      distances[off] = curK;
   269
   270      // Base case: reached an index k away from the origin.
   271      if (curK >= k) return E_SUCCESS;
   272
   273      // Recurse to all neighbors in no particular order.
   274      for (int i = 0; i < 6; i++) {
   275          int rotations = 0;
   276          H3Index nextNeighbor;
   277          H3Error neighborResult = h3NeighborRotations(origin, DIRECTIONS[i],
   278                                                       &rotations, &nextNeighbor);
   279          if (neighborResult != E_PENTAGON) {
   280              // E_PENTAGON is an expected case when trying to traverse off of
   281              // pentagons.
   282              if (neighborResult != E_SUCCESS) {
   283                  return neighborResult;
   284              }
   285              neighborResult = _gridDiskDistancesInternal(
   286                  nextNeighbor, k, out, distances, maxIdx, curK + 1);
   287              if (neighborResult) {
   288                  return neighborResult;
   289              }
   290          }
   291      }
   292      return E_SUCCESS;
   293  }
