   801   * @param h The H3Index.
   802   * @param fijk The FaceIJK address, initialized with the desired face
   803   *        and normalized base cell coordinates.
   804   * @return Returns 1 if the possibility of overage exists, otherwise 0.
   805   */
   806  int _h3ToFaceIjkWithInitializedFijk(H3Index h, FaceIJK *fijk) {
   807      CoordIJK *ijk = &fijk->coord;
   808      int res = H3_GET_RESOLUTION(h);
   809
   810      // center base cell hierarchy is entirely on this face
   811      int possibleOverage = 1;
   812      if (!_isBaseCellPentagon(H3_GET_BASE_CELL(h)) &&
   813          (res == 0 ||
   814           (fijk->coord.i == 0 && fijk->coord.j == 0 && fijk->coord.k == 0)))
   815          possibleOverage = 0;
   816
   817      for (int r = 1; r <= res; r++) {
   818          if (isResolutionClassIII(r)) {
   819              // Class III == rotate ccw
   820              _downAp7(ijk);
   821          } else {
   822              // Class II == rotate cw
   823              _downAp7r(ijk);
   824          }
   825
   826          _neighbor(ijk, H3_GET_INDEX_DIGIT(h, r));
   827      }
   828
   829      return possibleOverage;
   830  }
